using System.Diagnostics;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Dlss5InstallAssistant;

if (args.FirstOrDefault() == "--hold-lock")
{
    using var hold = new TargetLease(new GameCandidate { Executable = args[1] });
    File.WriteAllText(args[2], "locked"); while (!File.Exists(args[3])) Thread.Sleep(20); return 0;
}
if (args.FirstOrDefault() == "--crash")
{
    GpuCompatibility.TestAdapterNames = () => new[] { "NVIDIA GeForce RTX 5090" };
    var p = PackageManifest.LoadWithTrust(args[2], args[3]); var h = new VerifiedReShadeHost(args[4], ReShadeHost.PinnedHostSha256, ReShadeHost.PinnedSetupSha256, ReShadeHost.Version);
    Deployer.TestCheckpoint = phase => { if (phase == args[5]) Environment.Exit(92); };
    Deployer.Install(GameInspector.Inspect(args[1], null), p, h); return 3;
}
if (args.FirstOrDefault() == "--verify-production-package")
{
    var verified = Directory.Exists(args[1]) ? PackageManifest.Load(args[1]) :
        PackageImport.LoadSelected(args[1]);
    Console.WriteLine("VALID " + verified.Build + " " + verified.ArtifactId + " " +
                      verified.Files.Count + " files");
    return 0;
}
var hostPath = args.Length > 0 ? Path.GetFullPath(args[0]) : throw new ArgumentException("Provide verified official dxgi.dll fixture path.");
var host = new VerifiedReShadeHost(hostPath, ReShadeHost.PinnedHostSha256, ReShadeHost.PinnedSetupSha256, ReShadeHost.Version);
var passed = 0; var failed = 0;
void Check(bool value, string message) { if (!value) throw new Exception(message); }
void Reject(Action action, string message) { try { action(); } catch (Exception ex) when (ex is IOException or InvalidDataException or InvalidOperationException or JsonException or ArgumentException or CryptographicException) { return; } throw new Exception(message); }
void Test(string name, Action<Fixture> run)
{
    GpuCompatibility.TestAdapterNames = () => new[] { "NVIDIA GeForce RTX 5090" };
    using var f = new Fixture(host);
    try { run(f); passed++; Console.WriteLine("PASS " + name); }
    catch (Exception ex) { failed++; Console.WriteLine("FAIL " + name + ": " + ex); }
    finally { Deployer.TestCheckpoint = null; GpuCompatibility.TestAdapterNames = null; ReShadeFontConfig.TestFileExists = null; Launcher.TestStartRequest = null; Launcher.TestExactProcessRunning = null; Launcher.TestLaunchTimeout = TimeSpan.Zero; }
}
Test("signed fixture trusted only through test trust anchor", f => { Check(f.Package.Files.Count == 4, "signed package"); Reject(() => PackageManifest.Load(f.PackageDirectory), "untrusted test key accepted by production anchor"); });
Test("tampered manifest rejected before plan", f => { File.AppendAllText(Path.Combine(f.PackageDirectory, "manifest.json"), " "); Reject(() => f.Load(), "tampered manifest accepted"); });
Test("tampered payload rejected", f => { File.AppendAllText(f.Package.Files[0].Path is { } p ? Path.Combine(f.PackageDirectory, p) : "", "bad"); Reject(() => f.Load(), "tampered payload accepted"); });
Test("helper replacement after signed-envelope validation is rejected", f => { var envelope = PackageManifest.VerifyEnvelope(f.PackageDirectory, f.TrustKey); var addon = Path.Combine(f.PackageDirectory, f.Package.Files.Single(x => x.Role == "addon").Path); File.WriteAllBytes(addon, Fixture.Pe(98)); Reject(() => SafeFiles.OpenExpectedReadLease(addon, envelope.HashOf(Path.GetFileName(addon))), "post-validation helper replacement accepted"); });
Test("verified helper lease blocks replacement until child completion", f => { var envelope = PackageManifest.VerifyEnvelope(f.PackageDirectory, f.TrustKey); var addon = Path.Combine(f.PackageDirectory, f.Package.Files.Single(x => x.Role == "addon").Path); using var lease = SafeFiles.OpenExpectedReadLease(addon, envelope.HashOf(Path.GetFileName(addon))); Reject(() => File.WriteAllBytes(addon, Fixture.Pe(99)), "leased helper replaced"); });
Test("wrong artifact identity rejected even with valid signature", f => { f.Manifest["artifactId"] = "sha256:" + new string('0', 64); f.Sign(); Reject(() => f.Load(), "wrong artifact accepted"); });
Test("flat signed component ZIP imports without manual extraction", f => { var zip = f.ZipPackage(); var imported = PackageImport.LoadSelected(zip, Path.Combine(f.Root, "imports"), f.TrustKey); Check(imported.Build == f.Package.Build && imported.ArtifactId == f.Package.ArtifactId, "ZIP identity changed"); var direct = PackageImport.LoadSelected(Path.Combine(f.PackageDirectory, "manifest.json"), Path.Combine(f.Root, "imports"), f.TrustKey); Check(direct.ManifestSha256 == f.Package.ManifestSha256, "direct manifest import changed"); });
Test("ZIP import rejects nested and unsigned lightweight archives", f => { var cache = Path.Combine(f.Root, "imports"); var nested = Path.Combine(f.Root, "nested.zip"); using (var z = ZipFile.Open(nested, ZipArchiveMode.Create)) { var e = z.CreateEntry("folder/manifest.json"); using var w = new StreamWriter(e.Open()); w.Write("{}"); } Reject(() => PackageImport.LoadSelected(nested, cache, f.TrustKey), "nested ZIP accepted"); var light = Path.Combine(f.Root, "light.zip"); using (var z = ZipFile.Open(light, ZipArchiveMode.Create)) { var e = z.CreateEntry("DLSS5-test.addon64"); using var s = e.Open(); s.Write(Fixture.Pe(77)); } Reject(() => PackageImport.LoadSelected(light, cache, f.TrustKey), "unsigned addon-only ZIP accepted"); Check(!File.Exists(Path.Combine(f.Root, "manifest.json")), "ZIP escaped cache"); });
Test("signed traversal and ADS names rejected", f => { f.Manifest["files"]![0]!["path"] = "../evil.addon64"; f.Sign(); Reject(() => f.Load(), "traversal accepted"); f.Manifest["files"]![0]!["path"] = "x:evil.addon64"; f.Sign(); Reject(() => f.Load(), "ADS accepted"); });
Test("HD2 experimental edition is never accepted for automatic install", f => { f.Manifest["edition"] = "experimental-diagnostics"; f.Sign(); Reject(() => f.Load(), "HD2 experimental package accepted"); });
Test("unsupported signed profile remains inspection only", f => { f.Manifest["compatibleProfiles"]![0]!["id"] = "helldivers2"; f.Sign(); Reject(() => f.Load(), "HD2 profile accepted"); });
Test("actual PE machine and NGX exports required", f => { var pe = File.ReadAllBytes(f.Game.Executable); pe[0x84] = 0x64; pe[0x85] = 0xaa; File.WriteAllBytes(f.Game.Executable, pe); Check(!GameInspector.Inspect(f.Game.Executable, null).EvidenceConfirmed, "ARM64 accepted"); });
Test("manifest unrelated Steam id cannot make arbitrary EXE a profile", f => { f.Manifest["compatibleProfiles"]![0]!["executableSha256"] = new JsonArray(); f.Sign(); Reject(() => Deployer.Plan(f.Game, f.Load(), host), "AppId alone accepted"); });
Test("RTX50 package matches detected RTX50 adapter", f => { GpuCompatibility.TestAdapterNames = () => new[] { "Intel(R) UHD Graphics", "NVIDIA GeForce RTX 5090" }; Check(Deployer.Plan(f.Game, f.Package, host).Files.Count > 0, "matching package rejected"); });
Test("RTX50 package is rejected on RTX30-40 before any write", f => { GpuCompatibility.TestAdapterNames = () => new[] { "NVIDIA GeForce RTX 4090" }; Reject(() => Deployer.Plan(f.Game, f.Package, host), "mismatched package accepted"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "GPU mismatch wrote game files"); });
Test("mixed RTX generations are rejected before any write", f => { GpuCompatibility.TestAdapterNames = () => new[] { "NVIDIA GeForce RTX 4090", "NVIDIA GeForce RTX 5090" }; Reject(() => Deployer.Plan(f.Game, f.Package, host), "mixed generations accepted"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "mixed GPU check wrote game files"); });
Test("unknown NVIDIA adapter is rejected before any write", f => { GpuCompatibility.TestAdapterNames = () => new[] { "NVIDIA RTX 5000 Ada Generation" }; Reject(() => Deployer.Plan(f.Game, f.Package, host), "unknown adapter accepted"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "unknown GPU check wrote game files"); });
Test("fresh install colocates all four payloads and official loader", f => { var p = Deployer.Plan(f.Game, f.Package, host); Check(p.Files.Count(x => x.Destination.StartsWith(p.AddonDirectory) && x.Role is "addon" or "bridge" or "runtime" or "config") == 4, "payloads split"); Check(Deployer.Apply(p).Ok, "install"); Check(File.Exists(Path.Combine(p.AddonDirectory, "nvngx_dlssnr.dll")), "runtime not sibling"); Check(File.ReadAllText(Path.Combine(f.Game.Directory, "ReShade.ini")).Contains("[ADDON]\r\nAddonPath="), "wrong INI section"); Check(Deployer.Uninstall(f.Game).Ok, "uninstall"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "owned host left"); });
Test("fresh Chinese ReShade configuration includes an installed CJK font", f => { ReShadeFontConfig.TestFileExists = p => SafeFiles.PathEquals(p, ReShadeFontConfig.MicrosoftYaHei); var config = Deployer.Plan(f.Game, f.Package, host).Files.Single(x => x.Role == "reshade-config"); Check(config.Action == FileAction.Write && config.Content != null, "fresh ReShade config missing"); Check(Encoding.UTF8.GetString(config.Content!).Contains("[STYLE]\r\nFont=C:\\Windows\\Fonts\\msyh.ttc\r\n"), "fresh CJK font missing"); });
Test("existing official loader with absent AddonPath uses EXE directory", f => { f.ExistingHost("[GENERAL]\r\nEffectSearchPaths=.\\Shaders\r\n"); var p = Deployer.Plan(f.Game, f.Package, host); Check(SafeFiles.PathEquals(p.AddonDirectory, f.Game.Directory), "default path wrong"); Deployer.Apply(p); Deployer.Uninstall(f.Game); Check(File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "reused host deleted"); });
Test("Chinese first install adds YaHei transactionally and restores exact INI", f => { ReShadeFontConfig.TestFileExists = p => SafeFiles.PathEquals(p, ReShadeFontConfig.MicrosoftYaHei); var ini = Path.Combine(f.Game.Directory, "ReShade.ini"); var original = "[ADDON]\r\nAddonPath=.\\local\r\n\r\n[GENERAL]\r\nPresetPath=中文.ini\r\n"; f.ExistingHost(original); var before = File.ReadAllBytes(ini); var p = Deployer.Plan(f.Game, f.Package, host); var config = p.Files.Single(x => x.Role == "reshade-config"); Check(config.Action == FileAction.Write && config.Content != null, "font edit was not planned"); Check(Deployer.Apply(p).Ok, "font install"); Check(File.ReadAllText(ini).Contains("[STYLE]\r\nFont=C:\\Windows\\Fonts\\msyh.ttc\r\n"), "YaHei missing"); Check(Deployer.Uninstall(f.Game).Ok, "font uninstall"); Check(File.ReadAllBytes(ini).SequenceEqual(before), "original ReShade.ini not restored byte-for-byte"); });
Test("Chinese font fallback fills one blank Font and preserves a custom Font", f => { ReShadeFontConfig.TestFileExists = p => SafeFiles.PathEquals(p, ReShadeFontConfig.SimSun); f.ExistingHost("[ADDON]\n\n[STYLE]\nFont=   \nLatinFont=C:\\Fonts\\latin.ttf\n"); var p = Deployer.Plan(f.Game, f.Package, host); Check(Encoding.Latin1.GetString(p.Files.Single(x => x.Role == "reshade-config").Content!).Contains("Font=C:\\Windows\\Fonts\\simsun.ttc\n"), "SimSun fallback missing"); Deployer.Apply(p); Deployer.Uninstall(f.Game); File.WriteAllText(Path.Combine(f.Game.Directory, "ReShade.ini"), "[ADDON]\r\n\r\n[STYLE]\r\nFont=D:\\Fonts\\custom.ttf\r\n"); p = Deployer.Plan(f.Game, f.Package, host); Check(p.Files.Single(x => x.Role == "reshade-config").Action == FileAction.Reuse, "custom font overwritten"); });
Test("font configuration is skipped without a system CJK font and for English packages", f => { ReShadeFontConfig.TestFileExists = _ => false; f.ExistingHost("[ADDON]\r\n"); Check(Deployer.Plan(f.Game, f.Package, host).Files.Single(x => x.Role == "reshade-config").Action == FileAction.Reuse, "missing font changed INI"); ReShadeFontConfig.TestFileExists = _ => true; f.Manifest["language"] = "en"; f.Sign(); Check(Deployer.Plan(f.Game, f.Load(), host).Files.Single(x => x.Role == "reshade-config").Action == FileAction.Reuse, "English package changed font"); });
Test("font edit rollback uses the existing transaction backup", f => { ReShadeFontConfig.TestFileExists = p => SafeFiles.PathEquals(p, ReShadeFontConfig.MicrosoftYaHei); var original = "[ADDON]\r\nAddonPath=.\\local\r\n[STYLE]\r\nFont=\r\n"; f.ExistingHost(original); var ini = Path.Combine(f.Game.Directory, "ReShade.ini"); var before = File.ReadAllBytes(ini); var once = false; Deployer.TestCheckpoint = phase => { if (phase == "after-move" && !once) { once = true; throw new IOException("stop after font move"); } }; Reject(() => Deployer.Install(f.Game, f.Package, host), "font failure not injected"); Check(File.ReadAllBytes(ini).SequenceEqual(before), "rollback did not restore original font config"); });
Test("later managed upgrades do not introduce a font preference", f => { ReShadeFontConfig.TestFileExists = _ => false; Deployer.Install(f.Game, f.Package, host); var ini = Path.Combine(f.Game.Directory, "ReShade.ini"); var before = File.ReadAllBytes(ini); ReShadeFontConfig.TestFileExists = _ => true; var p = Deployer.Plan(f.Game, f.Package, host); Check(p.Files.Single(x => x.Role == "reshade-config").Action == FileAction.Reuse, "upgrade rewrote ReShade font"); Deployer.Apply(p); Check(File.ReadAllBytes(ini).SequenceEqual(before), "upgrade changed ReShade.ini"); });
Test("ADDON section wins over unrelated GENERAL AddonPath", f => { f.ExistingHost("[GENERAL]\r\nAddonPath=C:\\not-the-addon-path\r\n[ADDON]\r\nAddonPath=.\\local\r\n"); Check(Deployer.Plan(f.Game, f.Package, host).AddonDirectory.EndsWith("local"), "section parse"); });
Test("shared external addon folder refused", f => { f.ExistingHost("[ADDON]\r\nAddonPath=" + f.Root + "\r\n"); Reject(() => Deployer.Plan(f.Game, f.Package, host), "shared path accepted"); });
Test("unknown loader and alternate entry not overwritten", f => { File.WriteAllText(Path.Combine(f.Game.Directory, "dxgi.dll"), "foreign"); Reject(() => Deployer.Plan(f.Game, f.Package, host), "unknown host accepted"); File.Delete(Path.Combine(f.Game.Directory, "dxgi.dll")); File.WriteAllText(Path.Combine(f.Game.Directory, "d3d12.dll"), "foreign"); Reject(() => Deployer.Plan(f.Game, f.Package, host), "second host accepted"); });
Test("same bytes reused and user configuration preserved", f => { f.ExistingHost("[ADDON]\r\n"); var runtime = Path.Combine(f.Game.Directory, "nvngx_dlssnr.dll"); File.Copy(Path.Combine(f.PackageDirectory, "nvngx_dlssnr.dll"), runtime); var ini = Path.Combine(f.Game.Directory, "nr_before_sr.ini"); File.WriteAllText(ini, "[NR]\r\nStrength=1.73\r\n"); var before = File.ReadAllBytes(ini); var p = Deployer.Plan(f.Game, f.Package, host); Check(p.Files.Single(x => x.Role == "runtime").Action == FileAction.Reuse, "runtime not reused"); Check(p.Files.Single(x => x.Role == "config") is { Action: FileAction.Reuse, Detail: var detail } && detail.Contains("用户改过配置"), "user-config preservation not explained"); Deployer.Apply(p); Deployer.Uninstall(f.Game); Check(File.Exists(runtime), "reused runtime deleted"); Check(File.ReadAllBytes(ini).SequenceEqual(before), "config modified"); });
Test("unchanged assistant-owned default follows a signed edition switch", f => { Check(Deployer.Install(f.Game, f.Package, host).Ok, "initial install"); f.ReplaceConfig("[NR]\r\nStrength=1.4\r\n"); var p = Deployer.Plan(f.Game, f.Load(), host); var config = p.Files.Single(x => x.Role == "config"); Check(config.Action == FileAction.Write && config.Detail.Contains("已知未修改"), "owned default was not upgraded"); Check(Deployer.Apply(p).Ok, "default upgrade"); Check(File.ReadAllText(config.Destination).Contains("Strength=1.4"), "new default not installed"); });
Test("signed known legacy default follows the selected edition", f => { f.ExistingHost("[ADDON]\r\nAddonPath=.\r\n"); var ini = Path.Combine(f.Game.Directory, "nr_before_sr.ini"); File.WriteAllText(ini, "[NR]\r\nStrength=1.0\r\n"); f.AllowExistingConfig(Fixture.Hash(ini)); f.ReplaceConfig("[NR]\r\nStrength=1.2\r\n"); var p = Deployer.Plan(f.Game, f.Load(), host); var config = p.Files.Single(x => x.Role == "config"); Check(config.Action == FileAction.Write && config.Detail.Contains("已知未修改"), "signed legacy default was preserved"); Check(Deployer.Apply(p).Ok && File.ReadAllText(ini).Contains("Strength=1.2"), "selected default not installed"); });
Test("signed optional feedback and crash scripts deploy and uninstall beside addon", f => { foreach (var (name, role) in new[] { ("Collect-Feedback.cmd", "feedback-launcher"), ("collect-feedback.ps1", "feedback-collector"), ("Collect-Crash-Feedback.cmd", "crash-feedback-launcher"), ("collect-crash-feedback.ps1", "crash-feedback-collector") }) { var source = Path.Combine(f.PackageDirectory, name); File.WriteAllText(source, "test script - never executed"); ((JsonArray)f.Manifest["files"]!).Add(new JsonObject { ["path"] = name, ["sha256"] = Fixture.Hash(source), ["bytes"] = new FileInfo(source).Length, ["role"] = role, ["source"] = "signed test fixture", ["target"] = "addon-directory", ["required"] = false, ["allowedExistingSha256"] = new JsonArray() }); } f.Sign(); var p = Deployer.Plan(f.Game, f.Load(), host); Check(p.Files.Count(x => x.Role.Contains("feedback")) == 4, "feedback payload absent"); Deployer.Apply(p); foreach (var name in new[] { "Collect-Feedback.cmd", "collect-feedback.ps1", "Collect-Crash-Feedback.cmd", "collect-crash-feedback.ps1" }) Check(File.Exists(Path.Combine(p.AddonDirectory, name)), "feedback wrong folder: " + name); Deployer.Uninstall(f.Game); foreach (var name in new[] { "Collect-Feedback.cmd", "collect-feedback.ps1", "Collect-Crash-Feedback.cmd", "collect-crash-feedback.ps1" }) Check(!File.Exists(Path.Combine(p.AddonDirectory, name)), "feedback not removed: " + name); });
Test("crash feedback roles require exact bounded file names", f => { var source = Path.Combine(f.PackageDirectory, "renamed-crash.ps1"); File.WriteAllText(source, "test script"); ((JsonArray)f.Manifest["files"]!).Add(new JsonObject { ["path"] = Path.GetFileName(source), ["sha256"] = Fixture.Hash(source), ["bytes"] = new FileInfo(source).Length, ["role"] = "crash-feedback-collector", ["source"] = "signed test fixture", ["target"] = "addon-directory", ["required"] = false, ["allowedExistingSha256"] = new JsonArray() }); f.Sign(); Reject(() => f.Load(), "renamed crash collector accepted"); });
Test("plugin MAX_PATH boundary refused before deployment", f => { var longer = Path.Combine(f.Root, new string('x', 170)); Directory.Move(f.Game.Directory, longer); f.Game.Executable = Path.Combine(longer, "fixture.exe"); Reject(() => Deployer.Plan(f.Game, f.Load(), host), "overlong addon path accepted"); Check(!File.Exists(Path.Combine(longer, "dxgi.dll")), "overlong plan wrote files"); });
Test("known legacy alias retired and restored; unknown alias refused", f => { f.ExistingHost("[ADDON]\r\n"); var old = Path.Combine(f.Game.Directory, "DLSS5-old.addon64"); File.WriteAllBytes(old, Fixture.Pe(5)); f.Manifest["legacyFiles"] = new JsonArray(new JsonObject { ["path"] = Path.GetFileName(old), ["sha256"] = Fixture.Hash(old) }); f.Sign(); Deployer.Install(f.Game, f.Load(), host); Check(!File.Exists(old), "old addon remains"); Deployer.Uninstall(f.Game); Check(File.Exists(old), "old addon not restored"); File.AppendAllText(old, "unknown"); Reject(() => Deployer.Plan(f.Game, f.Load(), host), "unknown alias accepted"); });
Test("second identical managed install retains original ownership", f => { Deployer.Install(f.Game, f.Package, host); Check(Deployer.Install(f.Game, f.Package, host).Ok, "reinstall"); Check(Deployer.Uninstall(f.Game).Ok, "uninstall"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "ownership lost on reuse"); });
Test("new addon filename upgrade leaves one addon and restores original baseline", f => { var original = f.ExistingOldRuntime(); var originalHash = Fixture.Hash(original); Deployer.Install(f.Game, f.Load(), host); var next = Path.Combine(f.PackageDirectory, "DLSS5-Test-v2.addon64"); File.WriteAllBytes(next, Fixture.Pe(91)); f.Manifest["files"]![0]!["path"] = Path.GetFileName(next); f.Manifest["files"]![0]!["sha256"] = Fixture.Hash(next); f.Manifest["files"]![0]!["bytes"] = new FileInfo(next).Length; f.Manifest["artifactId"] = "sha256:" + Fixture.Hash(next); f.Sign(); Deployer.Install(f.Game, f.Load(), host); Check(Directory.GetFiles(f.Game.Directory, "*.addon64").Length == 1, "duplicate addon after upgrade"); Check(Deployer.Uninstall(f.Game).Ok, "uninstall update"); Check(Fixture.Hash(original) == originalHash, "original backup mapping lost on update"); });
foreach (var phase in new[] { "before-record", "after-backup", "before-move", "after-move", "before-installed", "after-installed" })
Test("rollback at " + phase + " cannot undo later success", f => { var once = false; Deployer.TestCheckpoint = step => { if (step == phase && !once) { once = true; throw new IOException("injected " + phase); } }; Reject(() => Deployer.Install(f.Game, f.Package, host), "failure not injected"); Deployer.TestCheckpoint = null; Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "failed host remains"); Check(Deployer.Install(f.Game, f.Package, host).Ok, "later install"); Check(Deployer.Recover(f.Game).Ok, "recover"); Check(File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "old journal undid new install"); });
Test("missing original backup preserves destination and recovery record", f => { var runtime = f.ExistingOldRuntime(); Deployer.Install(f.Game, f.Load(), host); f.DamageOriginalBackup(runtime, false); Check(!Deployer.Uninstall(f.Game).Ok, "missing backup reported success"); Check(File.Exists(runtime), "destination deleted"); Check(Deployer.ReadInstalled(f.Game) != null, "recovery record lost"); });
Test("corrupt original backup never restored", f => { var runtime = f.ExistingOldRuntime(); Deployer.Install(f.Game, f.Load(), host); var installed = Fixture.Hash(runtime); f.DamageOriginalBackup(runtime, true); Check(!Deployer.Uninstall(f.Game).Ok, "corrupt backup success"); Check(Fixture.Hash(runtime) == installed, "corrupt bytes restored"); });
Test("user edits and deletions survive uninstall", f => { Deployer.Install(f.Game, f.Package, host); var addonRoot = Path.Combine(f.Game.Directory, ".dlss5-addons"); File.WriteAllText(Path.Combine(addonRoot, "nr_before_sr.ini"), "user"); File.Delete(Path.Combine(addonRoot, "nvngx_dlssnr.dll")); Check(Deployer.Uninstall(f.Game).Ok, "uninstall"); Check(File.ReadAllText(Path.Combine(addonRoot, "nr_before_sr.ini")) == "user", "edit overwritten"); Check(!File.Exists(Path.Combine(addonRoot, "nvngx_dlssnr.dll")), "deleted file restored"); });
Test("plan precondition stops target edits before apply", f => { var p = Deployer.Plan(f.Game, f.Package, host); File.WriteAllText(Path.Combine(f.Game.Directory, "dxgi.dll"), "user"); Reject(() => Deployer.Apply(p), "changed host overwritten"); Check(File.ReadAllText(Path.Combine(f.Game.Directory, "dxgi.dll")) == "user", "changed bytes lost"); });
Test("package changed after plan rejected", f => { var p = Deployer.Plan(f.Game, f.Package, host); File.AppendAllText(Path.Combine(f.PackageDirectory, "nr_before_sr.ini"), "changed"); Reject(() => Deployer.Apply(p), "changed source accepted"); });
Test("cancel before write leaves no installed file", f => { using var cancel = new CancellationTokenSource(); cancel.Cancel(); try { Deployer.Install(f.Game, f.Package, host, cancel.Token); throw new Exception("cancel ignored"); } catch (OperationCanceledException) { } Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "cancel left host"); });
Test("directory junction inserted at actual target after plan refused", f => { var p = Deployer.Plan(f.Game, f.Package, host); var outside = Path.Combine(f.Root, "outside"); Directory.CreateDirectory(outside); var sentinel = Path.Combine(outside, "nrchain_nvngx.dll"); File.WriteAllText(sentinel, "sentinel"); var link = p.AddonDirectory; Fixture.Junction(link, outside); try { Reject(() => Deployer.Apply(p), "post-plan junction accepted"); Check(File.ReadAllText(sentinel) == "sentinel", "external file changed"); } finally { Directory.Delete(link); } });
Test("state-directory junction refused before backups", f => { var outside = Path.Combine(f.Root, "outside"); Directory.CreateDirectory(outside); var link = Deployer.StateDirectory(f.Game); Fixture.Junction(link, outside); try { Reject(() => Deployer.Install(f.Game, f.Package, host), "state junction accepted"); Check(!Directory.EnumerateFileSystemEntries(outside).Any(), "external state written"); } finally { Directory.Delete(link); } });
Test("dangling target junction refused", f => { var p = Deployer.Plan(f.Game, f.Package, host); var missing = Path.Combine(f.Root, "does-not-exist"); Fixture.Junction(p.AddonDirectory, missing); try { Reject(() => Deployer.Apply(p), "dangling junction accepted"); Check(!Directory.Exists(missing), "dangling target materialized outside"); } finally { Directory.Delete(p.AddonDirectory); } });
Test("directory cannot be swapped while move checkpoint is in flight", f => { var pinned = false; Deployer.TestCheckpoint = phase => { if (phase == "before-move" && !pinned) { try { Directory.Move(f.Game.Directory, f.Game.Directory + "-moved"); } catch (IOException) { pinned = true; } } }; Deployer.Install(f.Game, f.Package, host); Check(pinned, "directory not pinned"); });
Test("second process lock blocks all mutations and launch", f => { var ready = Path.Combine(f.Root, "ready"); var release = Path.Combine(f.Root, "release"); using var child = Fixture.Child("--hold-lock", f.Game.Executable, ready, release); try { Check(SpinWait.SpinUntil(() => File.Exists(ready) || child.HasExited, 10000) && File.Exists(ready), "child lock missing"); Reject(() => Deployer.Install(f.Game, f.Package, host), "concurrent install"); Reject(() => Deployer.Uninstall(f.Game), "concurrent uninstall"); Reject(() => Deployer.Recover(f.Game), "concurrent recover"); Reject(() => Deployer.AcquireForLaunch(f.Game), "concurrent launch"); } finally { File.WriteAllText(release, "done"); child.WaitForExit(5000); } });
Test("delayed Steam launch keeps target locked until exact process appears", f => { using var requested = new ManualResetEventSlim(); var running = false; Launcher.TestStartRequest = _ => requested.Set(); Launcher.TestExactProcessRunning = _ => running; Launcher.TestLaunchTimeout = TimeSpan.FromSeconds(3); var launch = Launcher.StartAsync(f.Game); Check(requested.Wait(1000), "launch request missing"); Reject(() => Deployer.AcquireForLaunch(f.Game), "launch gap allowed mutation"); running = true; Check(launch.Wait(3000) && launch.IsCompletedSuccessfully, "launch did not transfer after exact process"); using var after = Deployer.AcquireForLaunch(f.Game); });
Test("launch timeout reports boundary and releases target lease", f => { Launcher.TestStartRequest = _ => { }; Launcher.TestExactProcessRunning = _ => false; Launcher.TestLaunchTimeout = TimeSpan.FromMilliseconds(150); try { Launcher.StartAsync(f.Game).GetAwaiter().GetResult(); throw new Exception("launch timeout accepted"); } catch (TimeoutException) { } using var after = Deployer.AcquireForLaunch(f.Game); });
foreach (var phase in new[] { "after-move", "after-installed" })
Test("process interruption recovery at " + phase, f => { using var child = Fixture.Child("--crash", f.Game.Executable, f.PackageDirectory, f.TrustKey, host.HostPath, phase); Check(child.WaitForExit(30000) && child.ExitCode == 92, "child did not interrupt"); Check(Deployer.Recover(f.Game).Ok, "recovery"); Check(!File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "interrupted host remains"); Check(Deployer.Install(f.Game, f.Package, host).Ok, "reinstall after interruption"); Deployer.Recover(f.Game); Check(File.Exists(Path.Combine(f.Game.Directory, "dxgi.dll")), "old interruption reverted later install"); });
Test("Steam fixture discovers bounded real candidate without scanning junction", f => { var steam = Path.Combine(f.Root, "steam"); var apps = Path.Combine(steam, "steamapps"); Directory.CreateDirectory(Path.Combine(apps, "common", "Example")); File.Copy(f.Game.Executable, Path.Combine(apps, "common", "Example", "game.exe")); File.WriteAllText(Path.Combine(apps, "appmanifest_123.acf"), "\"name\" \"Example\"\n\"installdir\" \"Example\""); Check(SteamScanner.Scan(steam).Single().SteamAppId == "123", "Steam discovery"); });
Test("running game is rejected by actual process identity", f => { var process = Process.GetCurrentProcess(); Reject(() => GameInspector.EnsureNotRunning(new GameCandidate { Executable = process.MainModule!.FileName }), "running process accepted"); });
Test("tampered ownership cannot restore outside game", f => { Deployer.Install(f.Game, f.Package, host); var statePath = Path.Combine(Deployer.StateDirectory(f.Game), "installed.json"); var state = JsonNode.Parse(File.ReadAllText(statePath))!; state["Files"]![0]!["RelativePath"] = "../sentinel.dll"; File.WriteAllText(statePath, state.ToJsonString()); var sentinel = Path.Combine(f.Root, "sentinel.dll"); File.WriteAllText(sentinel, "outside"); Reject(() => Deployer.Uninstall(f.Game), "tampered record accepted"); Check(File.ReadAllText(sentinel) == "outside", "external changed"); });
Test("helper returns nonzero for partial uninstall and preserves failure evidence", f => { var runtime = f.ExistingOldRuntime(); Deployer.Install(f.Game, f.Load(), host); f.DamageOriginalBackup(runtime, false); var id = Guid.NewGuid().ToString("N"); Directory.CreateDirectory(ElevationHelper.OperationsRoot); var request = Path.Combine(ElevationHelper.OperationsRoot, id + ".request.json"); var response = Path.Combine(ElevationHelper.OperationsRoot, id + ".response.json"); File.WriteAllText(request, JsonSerializer.Serialize(new HelperRequest { Id = id, Operation = "uninstall", Executable = f.Game.Executable })); try { Check(ElevationHelper.RunRequestAsync(request, Fixture.Hash(request)).GetAwaiter().GetResult() == 1, "helper falsely returned success"); Check(!JsonSerializer.Deserialize<HelperResponse>(File.ReadAllText(response))!.Ok, "response falsely successful"); Check(File.Exists(runtime), "helper deleted target"); } finally { File.Delete(request); File.Delete(response); } });
Test("helper rejects changed request, unknown operation and untrusted path", f => { var outside = Path.Combine(f.Root, "request.json"); File.WriteAllText(outside, "{}"); Check(ElevationHelper.RunRequestAsync(outside, Fixture.Hash(outside)).GetAwaiter().GetResult() != 0, "outside request accepted"); var id = Guid.NewGuid().ToString("N"); Directory.CreateDirectory(ElevationHelper.OperationsRoot); var request = Path.Combine(ElevationHelper.OperationsRoot, id + ".request.json"); var response = Path.Combine(ElevationHelper.OperationsRoot, id + ".response.json"); File.WriteAllText(request, JsonSerializer.Serialize(new HelperRequest { Id = id, Operation = "launch", Executable = f.Game.Executable })); var originalHash = Fixture.Hash(request); File.AppendAllText(request, " "); try { Check(ElevationHelper.RunRequestAsync(request, originalHash).GetAwaiter().GetResult() != 0, "changed request accepted"); File.WriteAllText(request, JsonSerializer.Serialize(new HelperRequest { Id = id, Operation = "launch", Executable = f.Game.Executable })); Check(ElevationHelper.RunRequestAsync(request, Fixture.Hash(request)).GetAwaiter().GetResult() != 0, "helper launched game"); } finally { File.Delete(request); if (File.Exists(response)) File.Delete(response); } });
Test("runtime v2 binds current process and exact artifact rather than version", f =>
{
    using var process = Process.GetCurrentProcess(); var game = new GameCandidate { Executable = process.MainModule!.FileName }; var stateDir = Deployer.StateDirectory(game); var statePath = Path.Combine(stateDir, "installed.json");
    var runtimeRoot = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "DLSS5InstallAssistant", "runtime"); Directory.CreateDirectory(runtimeRoot); var path = Path.Combine(runtimeRoot, process.Id + ".json");
    var oldState = File.Exists(statePath) ? File.ReadAllBytes(statePath) : null; var oldStatus = File.Exists(path) ? File.ReadAllBytes(path) : null;
    var sha = new string('A', 64); var commit = new string('a', 40); var state = new InstalledState { TransactionId = Guid.NewGuid().ToString("N"), Executable = game.Executable, Build = "same-version", PayloadSourceCommit = commit, AddonRelativePath = "runtime-fixture.addon64", AddonSha256 = sha, ArtifactId = "sha256:" + sha };
    Directory.CreateDirectory(stateDir); File.WriteAllText(statePath, JsonSerializer.Serialize(state));
    var status = new RuntimeStatus { Schema = "dlss5-runtime-status/v2", ProcessId = process.Id, ProcessStartedAt = new DateTimeOffset(process.StartTime.ToUniversalTime()), UpdatedAt = DateTimeOffset.UtcNow, Executable = game.Executable, BuildId = "same-version", SourceCommit = commit, SourceDirty = false, AddonIdentityStatus = "verified", AddonPath = Path.Combine(game.Directory, state.AddonRelativePath), AddonSha256 = sha, ArtifactId = state.ArtifactId, State = "active", Active = true, NativeSrObserved = true, NrEvaluations = 12, TransferSubmitted = 10, ConfigGeneration = 1, BypassReason = "none" };
    void Publish() => File.WriteAllText(path, JsonSerializer.Serialize(status));
    try
    {
        Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: true, Active: true }, "valid v2 rejected");
        status.AddonSha256 = new string('B', 64); Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: false }, "same-version different binary accepted");
        status.AddonSha256 = sha; status.AddonPath = Path.Combine(game.Directory, "another.addon64"); Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: false }, "different loaded path accepted");
        status.AddonPath = Path.Combine(game.Directory, state.AddonRelativePath); status.BuildId = "reused-version"; Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: false }, "different build identity accepted");
        status.BuildId = state.Build; status.SourceCommit = new string('b', 40); Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: false }, "different source commit accepted");
        status.SourceCommit = commit; status.SourceDirty = true; Publish(); Check(Launcher.ReadStatus(game) is { DeploymentMatches: false }, "dirty runtime identity accepted");
        status.SourceDirty = false;
        status.AddonPath = Path.Combine(game.Directory, state.AddonRelativePath); status.State = "bypassed"; Publish(); Check(Launcher.ReadStatus(game) is { Active: false }, "bypass remained active");
        status.Schema = "dlss5-runtime-status/v1"; Publish(); Check(Launcher.ReadStatus(game) == null, "legacy status accepted");
        status.Schema = "dlss5-runtime-status/v2"; status.UpdatedAt = DateTimeOffset.UtcNow.AddSeconds(30); Publish(); Check(Launcher.ReadStatus(game) == null, "future status accepted");
        status.UpdatedAt = DateTimeOffset.UtcNow; status.ProcessStartedAt = status.ProcessStartedAt!.Value.AddSeconds(-10); Publish(); Check(Launcher.ReadStatus(game) == null, "reused PID status accepted");
    }
    finally { if (oldState == null) File.Delete(statePath); else File.WriteAllBytes(statePath, oldState); if (oldStatus == null) File.Delete(path); else File.WriteAllBytes(path, oldStatus); }
});
Console.WriteLine($"RESULT: {passed} passed, {failed} failed");
return failed == 0 ? 0 : 1;

sealed class Fixture : IDisposable
{
    public string Root { get; } = Path.Combine(Path.GetTempPath(), "DLSS5-Installer-Test-" + Guid.NewGuid().ToString("N"));
    public string PackageDirectory { get; }
    public GameCandidate Game { get; }
    public PackageManifest Package => Load();
    public JsonObject Manifest { get; }
    public string TrustKey => Convert.ToBase64String(key.ExportSubjectPublicKeyInfo());
    readonly ECDsa key = ECDsa.Create(ECCurve.NamedCurves.nistP256);
    public Fixture(VerifiedReShadeHost host)
    {
        Directory.CreateDirectory(Root); var game = Path.Combine(Root, "游戏"); Directory.CreateDirectory(game); var exe = Path.Combine(game, "fixture.exe"); File.WriteAllBytes(exe, Pe(1)); File.WriteAllBytes(Path.Combine(game, "nvngx_dlss.dll"), Pe(2)); Game = GameInspector.Inspect(exe, null);
        if (!Game.EvidenceConfirmed) throw new Exception("PE fixture must satisfy actual D3D12/NGX parser");
        PackageDirectory = Path.Combine(Root, "package"); Directory.CreateDirectory(PackageDirectory); var files = new JsonArray(); var index = 3;
        foreach (var (name, role) in new[] { ("DLSS5-Test-v1.addon64", "addon"), ("nrchain_nvngx.dll", "bridge"), ("nvngx_dlssnr.dll", "runtime"), ("nr_before_sr.ini", "config") })
        {
            var path = Path.Combine(PackageDirectory, name); if (role == "config") File.WriteAllText(path, "[NR]\r\nStrength=1.2\r\n"); else File.WriteAllBytes(path, Pe(index++));
            files.Add(new JsonObject { ["path"] = name, ["sha256"] = Hash(path), ["bytes"] = new FileInfo(path).Length, ["role"] = role, ["source"] = "test-fixture", ["target"] = "addon-directory", ["required"] = true, ["allowedExistingSha256"] = new JsonArray() });
        }
        Manifest = new JsonObject { ["schema"] = "dlss5-install-manifest/v4", ["id"] = "nr-before-sr", ["build"] = "fixture-build", ["edition"] = "compatibility-fallback", ["payloadSourceCommit"] = new string('a', 40), ["artifactId"] = "sha256:" + files[0]!["sha256"]!.GetValue<string>(), ["gpuFamily"] = "RTX50", ["language"] = "zh-CN", ["nativeD3D12"] = true, ["onlineAllowed"] = false, ["files"] = files,
            ["compatibleProfiles"] = new JsonArray(new JsonObject { ["id"] = "cyberpunk2077-d3d12", ["verifiedNativeD3D12"] = true, ["evidence"] = "synthetic signed PE fixture", ["executableSha256"] = new JsonArray(Game.ExecutableSha256) }), ["legacyFiles"] = new JsonArray() };
        Sign();
    }
    public PackageManifest Load() => PackageManifest.LoadWithTrust(PackageDirectory, TrustKey);
    public void ReplaceConfig(string content)
    {
        var file = Manifest["files"]!.AsArray().Select(x => x!.AsObject()).Single(x => x["role"]!.GetValue<string>() == "config");
        var path = Path.Combine(PackageDirectory, file["path"]!.GetValue<string>()); File.WriteAllText(path, content);
        file["sha256"] = Hash(path); file["bytes"] = new FileInfo(path).Length; Sign();
    }
    public void AllowExistingConfig(string hash)
    {
        var file = Manifest["files"]!.AsArray().Select(x => x!.AsObject()).Single(x => x["role"]!.GetValue<string>() == "config");
        file["allowedExistingSha256"] = new JsonArray(hash); Sign();
    }
    public string ZipPackage()
    {
        var path = Path.Combine(Root, "signed-package.zip");
        ZipFile.CreateFromDirectory(PackageDirectory, path, CompressionLevel.Optimal,
                                    includeBaseDirectory: false);
        return path;
    }
    public void Sign()
    {
        File.WriteAllText(Path.Combine(PackageDirectory, "manifest.json"), Manifest.ToJsonString()); var keyId = Convert.ToHexString(SHA256.HashData(key.ExportSubjectPublicKeyInfo()))[..16];
        var records = Directory.GetFiles(PackageDirectory).Where(x => Path.GetFileName(x) is not ("RELEASE_MANIFEST.json" or "RELEASE_MANIFEST.sig")).Select(x => new { path = Path.GetFileName(x), bytes = new FileInfo(x).Length, sha256 = Hash(x) }).ToArray();
        var bytes = JsonSerializer.SerializeToUtf8Bytes(new { schema = "dlss5-release-manifest-v1", keyId, files = records }); File.WriteAllBytes(Path.Combine(PackageDirectory, "RELEASE_MANIFEST.json"), bytes);
        File.WriteAllText(Path.Combine(PackageDirectory, "RELEASE_MANIFEST.sig"), JsonSerializer.Serialize(new { schema = "dlss5-release-signature-v1", algorithm = "ECDSA-P256-SHA256", keyId, manifest = "RELEASE_MANIFEST.json", manifestSha256 = Convert.ToHexString(SHA256.HashData(bytes)), signatureBase64 = Convert.ToBase64String(key.SignData(bytes, HashAlgorithmName.SHA256)) }));
    }
    public void ExistingHost(string ini) { File.Copy(ProgramHostPath(), Path.Combine(Game.Directory, "dxgi.dll")); File.WriteAllText(Path.Combine(Game.Directory, "ReShade.ini"), ini); }
    static string ProgramHostPath() => Path.GetFullPath(Environment.GetCommandLineArgs()[1]);
    public string ExistingOldRuntime() { ExistingHost("[ADDON]\r\n"); var file = Path.Combine(Game.Directory, "nvngx_dlssnr.dll"); File.WriteAllBytes(file, Pe(42)); Manifest["files"]![2]!["allowedExistingSha256"] = new JsonArray(Hash(file)); Sign(); return file; }
    public void DamageOriginalBackup(string path, bool corrupt)
    { var state = Deployer.ReadInstalled(Game)!; var record = state.Files.Single(x => SafeFiles.PathEquals(Path.Combine(Game.Directory, x.RelativePath), path)); var backup = Path.Combine(Deployer.StateDirectory(Game), "transactions", record.BackupTransactionId, record.BackupFile); if (corrupt) File.WriteAllText(backup, "corrupt"); else File.Delete(backup); }
    public static string Hash(string path) => Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
    public static Process Child(params string[] args) { var p = new ProcessStartInfo(Environment.ProcessPath!) { UseShellExecute = false, CreateNoWindow = true }; foreach (var arg in args) p.ArgumentList.Add(arg); return Process.Start(p)!; }
    public static void Junction(string path, string target) { var p = new ProcessStartInfo("cmd.exe") { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true }; p.ArgumentList.Add("/c"); p.ArgumentList.Add("mklink"); p.ArgumentList.Add("/J"); p.ArgumentList.Add(path); p.ArgumentList.Add(target); using var process = Process.Start(p)!; process.WaitForExit(); if (process.ExitCode != 0 || (File.GetAttributes(path) & FileAttributes.ReparsePoint) == 0) throw new Exception("Junction fixture could not be created."); }
    public static byte[] Pe(int seed)
    {
        var b = new byte[8192]; void U16(int at, ushort n) => BitConverter.GetBytes(n).CopyTo(b, at); void U32(int at, uint n) => BitConverter.GetBytes(n).CopyTo(b, at); void Text(int at, string s) => Encoding.ASCII.GetBytes(s).CopyTo(b, at);
        b[0] = 77; b[1] = 90; U32(0x3c, 0x80); Text(0x80, "PE\0\0"); U16(0x84, 0x8664); U16(0x86, 1); U16(0x94, 0xf0); U16(0x96, 0x2022);
        U16(0x98, 0x20b); U32(0x98 + 32, 0x1000); U32(0x98 + 36, 0x200); U32(0x98 + 56, 0x3000); U32(0x98 + 60, 0x200); U32(0x98 + 108, 16);
        U32(0x98 + 112, 0x1100); U32(0x98 + 116, 0x200); U32(0x98 + 120, 0x1000); U32(0x98 + 124, 40);
        Text(0x188, ".rdata"); U32(0x190, 0x1800); U32(0x194, 0x1000); U32(0x198, 0x1800); U32(0x19c, 0x200); U32(0x1ac, 0x40000040);
        U32(0x20c, 0x1080); Text(0x280, "d3d12.dll\0"); U32(0x300 + 24, 2); U32(0x300 + 32, 0x1140); U32(0x340, 0x1160); U32(0x344, 0x11a0);
        Text(0x360, "NVSDK_NGX_D3D12_CreateFeature\0"); Text(0x3a0, "NVSDK_NGX_D3D12_EvaluateFeature\0"); U32(7000, (uint)seed); return b;
    }
    public void Dispose() { key.Dispose(); var full = Path.GetFullPath(Root); if (full.StartsWith(Path.GetFullPath(Path.GetTempPath()), StringComparison.OrdinalIgnoreCase) && Path.GetFileName(full).StartsWith("DLSS5-Installer-Test-")) { try { Directory.Delete(full, true); } catch { } } }
}
